<?php require "config.php"; $page_title="Track Status | SFHS"; $row=null;$error=""; if($_SERVER["REQUEST_METHOD"]==="POST"){$code=strtoupper(trim($_POST["tracking_code"]??""));$s=$conn->prepare("SELECT tracking_code,category,subject,status,created_at,updated_at FROM complaints WHERE tracking_code=?");$s->bind_param("s",$code);$s->execute();$row=$s->get_result()->fetch_assoc();$s->close();if(!$row)$error="No submission found. Check your tracking code.";} require "includes/header.php"; ?>
<h1>Track your submission</h1><p class="muted">Enter the tracking code shown after submitting your concern.</p><form class="form narrow" method="post"><label>Tracking code</label><input name="tracking_code" required placeholder="SFHS-XXXXXXXXXX"><button class="btn">Check status</button><?php if($error): ?><p class="error"><?=e($error)?></p><?php endif; ?></form>
<?php if($row): ?><div class="panel"><span class="badge"><?=e($row["status"])?></span><h2><?=e($row["subject"])?></h2><p><?=e($row["tracking_code"])?> · <?=e($row["category"])?></p><div class="steps"><?php foreach(["New","In Review","Action Taken","Closed"] as $st): ?><span class="<?=array_search($row["status"],["New","In Review","Action Taken","Closed"],true)>=array_search($st,["New","In Review","Action Taken","Closed"],true)?"done":""?>"><?=e($st)?></span><?php endforeach; ?></div><p class="muted small">Submitted <?=e($row["created_at"])?> · Updated <?=e($row["updated_at"])?></p></div><?php endif; ?><?php require "includes/footer.php"; ?>